public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> results = new ArrayList<>();
    if (nums == null) {
        return results;
    }
    boolean[] used = new boolean[nums.length];
    List<Integer> current = new ArrayList<>();
    backtrack(nums, used, current, results);
    return results;
}

private void backtrack(int[] nums, boolean[] used, List<Integer> current, List<List<Integer>> results) {
    if (current.size() == nums.length) {
        results.add(new ArrayList<>(current));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (used[i]) continue;
        used[i] = true;
        current.add(nums[i]);
        backtrack(nums, used, current, results);
        current.remove(current.size() - 1);
        used[i] = false;
    }
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    // Normalize strings: treat null as empty string
    for (int i = 0; i < strings.size(); i++) {
        if (strings.get(i) == null) {
            strings.set(i, "");
        }
    }

    // If any string is empty, no common non-empty substring exists
    for (String s : strings) {
        if (s.isEmpty()) {
            return 0;
        }
    }

    // Find the length of the shortest string
    int maxPossibleLength = Integer.MAX_VALUE;
    for (String s : strings) {
        if (s.length() < maxPossibleLength) {
            maxPossibleLength = s.length();
        }
    }

    int low = 1;
    int high = maxPossibleLength;
    int best = 0;

    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (hasCommonSubstring(strings, mid)) {
            best = mid;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }

    return best;
}

private boolean hasCommonSubstring(List<String> strings, int len) {
    Set<String> common = null;

    for (String s : strings) {
        Set<String> candidate = new HashSet<>();

        // Add all substrings of length len from the original string
        int n = s.length();
        if (n >= len) {
            for (int i = 0; i <= n - len; i++) {
                candidate.add(s.substring(i, i + len));
            }
        }

        // Add all substrings of length len from the reversed string
        String rev = new StringBuilder(s).reverse().toString();
        int r = rev.length();
        if (r >= len) {
            for (int i = 0; i <= r - len; i++) {
                candidate.add(rev.substring(i, i + len));
            }
        }

        if (common == null) {
            common = candidate;
        } else {
            common.retainAll(candidate);
        }

        if (common == null || common.isEmpty()) {
            return false;
        }
    }

    return !common.isEmpty();
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) {
        return 0;
    }
    int rows = grid.length;
    boolean[][] visited = new boolean[rows][];
    for (int i = 0; i < rows; i++) {
        // Handle potential null or irregular rows
        int cols = (grid[i] == null) ? 0 : grid[i].length;
        visited[i] = new boolean[cols];
    }

    int deposits = 0;
    for (int r = 0; r < rows; r++) {
        if (grid[r] == null) {
            continue;
        }
        for (int c = 0; c < grid[r].length; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                deposits++;
                dfs(r, c, grid, visited);
            }
        }
    }
    return deposits;
}

private static void dfs(int r, int c, char[][] grid, boolean[][] visited) {
    if (r < 0 || r >= grid.length) {
        return;
    }
    if (grid[r] == null || c < 0 || c >= grid[r].length) {
        return;
    }
    if (visited[r][c] || grid[r][c] != '@') {
        return;
    }
    visited[r][c] = true;
    dfs(r + 1, c, grid, visited);
    dfs(r - 1, c, grid, visited);
    dfs(r, c + 1, grid, visited);
    dfs(r, c - 1, grid, visited);
}

public static int countPrefixWords(java.util.List<String> wordList, String prefix) {
    // Validate input: if either argument is null, consider it as no words to count
    if (wordList == null || prefix == null) {
        return 0;
    }

    int count = 0;
    for (String word : wordList) {
        // Skip null entries in the list
        if (word == null) {
            continue;
        }
        // Count words that start with the given prefix
        if (word.startsWith(prefix)) {
            count++;
        }
    }
    return count;
}

