    for (int num : numbers) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    int count = 0;
    for (int num : numbers) {
        if (num % 2 == 0) {
            int half = num / 2;
            Integer f = freq.get(half);
            if (f != null) {
                if (half == num) {
                    if (f > 1) {
                        count++;
                    }
                } else {
                    count++;
                }
            }
        }
    }
    return count;
}

