public static String convertDatesToWeekdays(String date) {
    if (date == null) {
        throw new IllegalArgumentException("Input date string cannot be null");
    }
    String[] parts = date.trim().split("\\s+");
    if (parts.length != 3) {
        throw new IllegalArgumentException("Input must be in format \"MM dd yyyy\"");
    }
    try {
        int month = Integer.parseInt(parts[0]);
        int day = Integer.parseInt(parts[1]);
        int year = Integer.parseInt(parts[2]);

        java.time.LocalDate localDate = java.time.LocalDate.of(year, month, day);
        java.time.Month monthObj = localDate.getMonth();
        String monthName = monthObj.getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
        int dayOfMonth = localDate.getDayOfMonth();
        String weekday = localDate.getDayOfWeek().getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);

        return monthName + " " + dayOfMonth + ", " + year + " is a " + weekday;
    } catch (NumberFormatException | java.time.DateTimeException e) {
        throw new IllegalArgumentException("Invalid date format or value", e);
    }
}

public int[] twoSum(int[] nums, int target) {
    if (nums == null || nums.length < 2) {
        throw new IllegalArgumentException("Input array must contain at least two numbers.");
    }
    for (int i = 0; i < nums.length - 1; i++) {
        for (int j = i + 1; j < nums.length; j++) {
            if (nums[i] + nums[j] == target) {
                return new int[]{i, j};
            }
        }
    }
    throw new IllegalArgumentException("No two-sum solution exists.");
}

public int search(int[] nums, int target) {
    if (nums == null || nums.length == 0) {
        return -1;
    }
    int left = 0;
    int right = nums.length - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (nums[mid] == target) {
            return mid;
        }
        // Determine which side is sorted
        if (nums[left] <= nums[mid]) {
            // Left side is sorted
            if (nums[left] <= target && target < nums[mid]) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        } else {
            // Right side is sorted
            if (nums[mid] < target && target <= nums[right]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
    }
    return -1;
}

public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        return 0.0;
    }
    int n = arr.length;
    int trimCount = (int) Math.floor(n * 0.05);
    if (trimCount == 0) {
        double sum = 0.0;
        for (int v : arr) {
            sum += v;
        }
        return sum / n;
    }
    java.util.Arrays.sort(arr);
    double sum = 0.0;
    int remaining = n - 2 * trimCount;
    for (int i = trimCount; i < trimCount + remaining; i++) {
        sum += arr[i];
    }
    return sum / remaining;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) {
        return false;
    }
    int n = arr.length;
    if (n % 2 != 0) {
        return false;
    }
    int[] freq = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k;
        freq[r]++;
    }

    // remainder 0 must be even
    if (freq[0] % 2 != 0) {
        return false;
    }

    // if k is even, remainder k/2 must also be even
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) {
            return false;
        }
    }

    // check other remainders
    for (int r = 1; r <= k / 2; r++) {
        int complement = k - r;
        if (r == complement) { // already handled for even k
            continue;
        }
        if (freq[r] != freq[complement]) {
            return false;
        }
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0 || edges == null || hasApple == null || hasApple.length != n) {
        throw new IllegalArgumentException("Invalid input parameters");
    }
    List<Integer>[] graph = new ArrayList[n];
    for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
    if (edges.length != n - 1) {
        throw new IllegalArgumentException("Edges length must be n-1 for a tree");
    }
    for (int[] e : edges) {
        if (e == null || e.length != 2) {
            throw new IllegalArgumentException("Each edge must have two endpoints");
        }
        int u = e[0], v = e[1];
        if (u < 0 || u >= n || v < 0 || v >= n) {
            throw new IllegalArgumentException("Edge endpoints out of bounds");
        }
        graph[u].add(v);
        graph[v].add(u);
    }

    boolean[] visited = new boolean[n];
    return dfs(0, -1, graph, hasApple, visited);
}

private int dfs(int node, int parent, List<Integer>[] graph, boolean[] hasApple, boolean[] visited) {
    visited[node] = true;
    int total = 0;
    for (int child : graph[node]) {
        if (child == parent) continue;
        int childCost = dfs(child, node, graph, hasApple, visited);
        if (childCost > 0 || hasApple[child]) {
            total += childCost + 2;
        }
    }
    // If this node has an apple but no children with apples, childCost==0 and
    // hasApple[node] may be true, but we do not need to add time here.
    // The parent will account for traversing to this node.
    return total;
}

public String sortString(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    // Frequency array for ASCII characters
    int[] freq = new int[256];
    for (char c : s.toCharArray()) {
        freq[c]++; // char is implicitly converted to int index
    }
    int remaining = s.length();
    StringBuilder result = new StringBuilder();

    while (remaining > 0) {
        // Ascending phase
        int prev = -1; // no previous character at start
        while (true) {
            int start = (prev == -1) ? 0 : prev + 1; // next smallest strictly greater
            int pick = -1;
            for (int i = start; i < 256; i++) {
                if (freq[i] > 0) {
                    pick = i;
                    break;
                }
            }
            if (pick == -1) {
                break; // cannot pick more in ascending phase
            }
            freq[pick]--;
            remaining--;
            result.append((char) pick);
            prev = pick;
        }

        // Descending phase
        prev = -1; // reset previous character
        while (true) {
            int start = (prev == -1) ? 255 : prev - 1; // next largest strictly smaller
            int pick = -1;
            for (int i = start; i >= 0; i--) {
                if (freq[i] > 0) {
                    pick = i;
                    break;
                }
            }
            if (pick == -1) {
                break; // cannot pick more in descending phase
            }
            freq[pick]--;
            remaining--;
            result.append((char) pick);
            prev = pick;
        }
    }

    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) {
        return false;
    }
    long totalSum = 0;
    for (int v : nums) {
        totalSum += v;
    }

    // dp[k] contains all achievable sums using k elements
    @SuppressWarnings("unchecked")
    Set<Long>[] dp = new Set[n + 1];
    for (int i = 0; i <= n; i++) {
        dp[i] = new HashSet<>();
    }
    dp[0].add(0L);

    for (int val : nums) {
        // Iterate from higher k to avoid overwriting data needed for this iteration
        for (int k = n - 1; k >= 1; k--) {
            if (dp[k - 1].isEmpty()) {
                continue;
            }
            for (Long prev : dp[k - 1]) {
                dp[k].add(prev + val);
            }
        }
    }

    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) {
            continue; // target sum not an integer
        }
        long target = (totalSum * k) / n;
        if (dp[k].contains(target)) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    // Handle null or empty input
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;

    // If there is only one step, you can start at step 1 (outside the staircase) and incur zero cost.
    if (n == 1) {
        return 0;
    }

    // dp[0] = dp[1] = 0 because you can start before step 0 or before step 1 with no cost.
    int prev2 = 0; // dp[i-2]
    int prev1 = 0; // dp[i-1]

    // Compute dp[i] iteratively
    for (int i = 2; i <= n; i++) {
        int costFromPrev1 = prev1 + cost[i - 1];
        int costFromPrev2 = prev2 + cost[i - 2];
        int cur = Math.min(costFromPrev1, costFromPrev2);
        prev2 = prev1;
        prev1 = cur;
    }

    return prev1;
}

public int uniqueMorseRepresentations(String[] words) {
    if (words == null || words.length == 0) {
        return 0;
    }
    String[] morse = {".-","-...","-.-.","-..",".","..-.","--.","....","..",".-..","--","-.",
                      "---",".--.", "--.-",".-.", "...","-","..-","...-",".--","-..-","-.--","--.."};
    Set<String> unique = new HashSet<>();
    for (String word : words) {
        if (word == null) {
            continue;
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < word.length(); i++) {
            char c = word.charAt(i);
            if (c >= 'a' && c <= 'z') {
                sb.append(morse[c - 'a']);
            } else if (c >= 'A' && c <= 'Z') {
                sb.append(morse[c - 'A']);
            } else {
                // ignore non-alphabetic characters
            }
        }
        unique.add(sb.toString());
    }
    return unique.size();
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0) {
        return false;
    }
    int n = s.length();
    if (n < k) {
        return false;
    }
    long total = 1L << k;
    Set<Long> seen = new HashSet<>((int) Math.min(total, Integer.MAX_VALUE));
    long mask = total - 1;
    long code = 0L;
    for (int i = 0; i < k; i++) {
        code = (code << 1) | (s.charAt(i) - '0');
    }
    seen.add(code);
    for (int i = k; i < n; i++) {
        code = ((code << 1) | (s.charAt(i) - '0')) & mask;
        seen.add(code);
        if (seen.size() == total) {
            return true;
        }
    }
    return seen.size() == total;
}

