public int minInsertions(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    int need = 0;   // number of '(' that need matching ')'
    int result = 0; // number of insertions performed
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            need++;
        } else if (c == ')') {
            need--;
            if (need == -1) { // unmatched ')'
                result++;   // insert '(' before this ')'
                need = 0;   // now it's balanced
            }
        } else {
            // Unexpected character; string should contain only '(' and ')'
            throw new IllegalArgumentException("Invalid character in input string");
        }
    }
    // Any remaining '(' need ')'
    return result + need;
}

public int minOperations(int n) {
    if (n <= 0) return 0;
    int t = n / 2;                     // first index with arr[i] >= n
    int m = n - t;                     // number of indices with surplus
    long a = 2L * t + 1 - n;            // first surplus value
    long result = (long) m * a + (long)(m - 1) * m; // sum of all surpluses
    // The result fits in int for the given problem constraints
    return (int) result;
}

public int highestAltitude(int[] gain) {
    // Handle null or empty input gracefully
    if (gain == null || gain.length == 0) {
        return 0;
    }
    int currentAltitude = 0;
    int highest = 0;
    for (int diff : gain) {
        currentAltitude += diff;
        if (currentAltitude > highest) {
            highest = currentAltitude;
        }
    }
    return highest;
}

public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) return 0;
    long maxEnding = nums[0];
    long maxSoFar = nums[0];
    long minEnding = nums[0];
    long minSoFar = nums[0];
    for (int i = 1; i < nums.length; i++) {
        long val = nums[i];
        maxEnding = Math.max(val, maxEnding + val);
        maxSoFar = Math.max(maxSoFar, maxEnding);
        minEnding = Math.min(val, minEnding + val);
        minSoFar = Math.min(minSoFar, minEnding);
    }
    long result = Math.max(maxSoFar, -minSoFar);
    if (result > Integer.MAX_VALUE) return Integer.MAX_VALUE;
    if (result < Integer.MIN_VALUE) return Integer.MIN_VALUE;
    return (int) result;
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        throw new IllegalArgumentException("k must be positive");
    }
    java.util.ArrayList<Integer> fib = new java.util.ArrayList<>();
    fib.add(1);
    fib.add(1);
    while (true) {
        int sz = fib.size();
        long next = (long) fib.get(sz - 1) + fib.get(sz - 2);
        if (next > k) {
            break;
        }
        fib.add((int) next);
    }
    int count = 0;
    for (int i = fib.size() - 1; i >= 0 && k > 0; i--) {
        if (fib.get(i) <= k) {
            k -= fib.get(i);
            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    // Validate input: n and k must be positive integers
    if (n <= 0 || k <= 0) {
        return -1;
    }

    java.util.List<Integer> factors = new java.util.ArrayList<>();

    // Find all factors of n
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            factors.add(i);
            int complement = n / i;
            if (complement != i) {
                factors.add(complement);
            }
        }
    }

    // Sort factors in ascending order
    java.util.Collections.sort(factors);

    // Return the k-th factor if it exists, otherwise -1
    if (k <= factors.size()) {
        return factors.get(k - 1);
    } else {
        return -1;
    }
}

public String makeGood(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder stack = new StringBuilder();
    for (char c : s.toCharArray()) {
        int len = stack.length();
        if (len > 0) {
            char top = stack.charAt(len - 1);
            if (Character.toUpperCase(top) == Character.toUpperCase(c) && top != c) {
                stack.deleteCharAt(len - 1);
                continue;
            }
        }
        stack.append(c);
    }
    return stack.toString();
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int n = s.length();
    int max = 0;
    java.util.Deque<java.util.AbstractMap.SimpleEntry<Integer, java.util.HashSet<String>>> stack =
            new java.util.ArrayDeque<>();
    stack.push(new java.util.AbstractMap.SimpleEntry<>(0, new java.util.HashSet<>()));

    while (!stack.isEmpty()) {
        java.util.AbstractMap.SimpleEntry<Integer, java.util.HashSet<String>> entry = stack.pop();
        int idx = entry.getKey();
        java.util.HashSet<String> used = entry.getValue();

        if (idx == n) {
            if (used.size() > max) {
                max = used.size();
            }
            continue;
        }

        for (int len = 1; idx + len <= n; len++) {
            String sub = s.substring(idx, idx + len);
            if (!used.contains(sub)) {
                java.util.HashSet<String> newSet = new java.util.HashSet<>(used);
                newSet.add(sub);
                stack.push(new java.util.AbstractMap.SimpleEntry<>(idx + len, newSet));
            }
        }
    }

    return max;
}

public int minOperations(String[] logs) {
    if (logs == null || logs.length == 0) {
        return 0;
    }
    int depth = 0;
    for (String log : logs) {
        if (log == null) {
            continue;
        }
        try {
            if (log.equals("../")) {
                if (depth > 0) {
                    depth--;
                }
            } else if (!log.equals("./") && log.endsWith("/")) {
                depth++;
            }
            // any other format is ignored
        } catch (Exception e) {
            // In case of unexpected runtime errors, ignore this log entry
            continue;
        }
    }
    return depth;
}

public String getSmallestString(int n, int k) {
    if (n <= 0) {
        return "";
    }
    if (k < n || k > 26L * n) { // use long to avoid overflow
        throw new IllegalArgumentException("k is not in the feasible range");
    }
    char[] chars = new char[n];
    // start with all 'a'
    for (int i = 0; i < n; i++) {
        chars[i] = 'a';
    }
    int remaining = k - n; // amount to add beyond all 'a'
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // can add up to 25 to go from 'a' to 'z'
        chars[i] = (char) ('a' + add);
        remaining -= add;
    }
    return new String(chars);
}

public static double calculateProbability(int n) {
    // The classic airplane seat problem: the first passenger chooses a random seat.
    // Subsequent passengers sit in their own seat if available, otherwise choose a random free seat.
    // The probability that the last passenger ends up in their own seat is:
    //   1 for n == 1 (only one seat),
    //   1/2 for n >= 2.
    //
    // Handle potential invalid input gracefully:
    if (n <= 0) {
        // Non-positive number of passengers is not meaningful in this context.
        return 0.0;
    }
    return (n == 1) ? 1.0 : 0.5;
}

public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        throw new IllegalArgumentException("Input array must not be null or empty");
    }
    int ones = 0, twos = 0;
    for (int num : nums) {
        // Update 'twos' with bits that have appeared twice so far
        twos |= ones & num;
        // Update 'ones' with bits that have appeared once so far
        ones ^= num;
        // Bits that have appeared three times will be cleared from both 'ones' and 'twos'
        int mask = ~(ones & twos);
        ones &= mask;
        twos &= mask;
    }
    return ones;
}

public static java.util.List<Integer> findSteppingNumbers(int low, int high) {
    java.util.List<Integer> result = new java.util.ArrayList<>();
    if (low > high) {
        return result; // empty list for invalid range
    }
    // Handle 0 separately since BFS starting from 1-9 won't generate it
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }
    java.util.Queue<Integer> queue = new java.util.LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        queue.add(i);
    }
    while (!queue.isEmpty()) {
        int num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num >= low) {
            result.add(num);
        }
        int lastDigit = num % 10;
        // Append lastDigit - 1 if it's valid
        if (lastDigit > 0) {
            int next = num * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.add(next);
            }
        }
        // Append lastDigit + 1 if it's valid
        if (lastDigit < 9) {
            int next = num * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.add(next);
            }
        }
    }
    java.util.Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n < 0) {
        return 0; // Invalid input, no positive numbers to count
    }
    long count = 0L;
    long factor = 1L; // current positional factor: 1, 10, 100, ...
    while (factor <= n) {
        long lower = n % factor;
        long cur = (n / factor) % 10L;
        long higher = n / (factor * 10L);
        if (cur == 0L) {
            count += higher * factor;
        } else if (cur == 1L) {
            count += higher * factor + lower + 1L;
        } else {
            count += (higher + 1L) * factor;
        }
        factor *= 10L;
    }
    return (int) count;
}

public static boolean isPowerOfTwo(int n) {
    // A power of two must be positive and have only a single bit set.
    if (n <= 0) {
        return false;
    }
    // Using the classic bitwise trick: n & (n-1) == 0 for powers of two.
    return (n & (n - 1)) == 0;
}

public static int addDigits(int num) {
    // Validate input: must be non‑negative.
    if (num < 0) {
        throw new IllegalArgumentException("Input must be non‑negative");
    }

    // Digital root formula: for num > 0, result is 1 + (num-1) % 9.
    // For num == 0, the digital root is 0.
    return (num == 0) ? 0 : 1 + (num - 1) % 9;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    if (n == 0) {
        return 0;
    }
    // Ensure all rows have the same length; otherwise, throw an exception.
    for (int i = 1; i < m; i++) {
        if (mat[i] == null || mat[i].length != n) {
            throw new IllegalArgumentException("All rows must have the same number of columns.");
        }
    }

    int[][] hor = new int[m][n];
    int[][] ver = new int[m][n];
    int[][] diag = new int[m][n];
    int[][] anti = new int[m][n];
    int maxLen = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] != 1) {
                // Treat any non-1 value as 0 (no contribution).
                hor[i][j] = ver[i][j] = diag[i][j] = anti[i][j] = 0;
                continue;
            }

            hor[i][j] = (j > 0) ? hor[i][j - 1] + 1 : 1;
            ver[i][j] = (i > 0) ? ver[i - 1][j] + 1 : 1;
            diag[i][j] = (i > 0 && j > 0) ? diag[i - 1][j - 1] + 1 : 1;
            anti[i][j] = (i > 0 && j < n - 1) ? anti[i - 1][j + 1] + 1 : 1;

            int cellMax = Math.max(Math.max(hor[i][j], ver[i][j]),
                                   Math.max(diag[i][j], anti[i][j]));
            if (cellMax > maxLen) {
                maxLen = cellMax;
            }
        }
    }
    return maxLen;
}

public static String addThousandSeparator(int n) {
    try {
        boolean isNegative = n < 0;
